INSERT INTO lamp_v18_guard SELECT IF((DATABASE() REGEXP '^mes_lamp_[A-Za-z0-9_]+$'),1,0);
INSERT INTO lamp_v18_guard SELECT IF((GET_LOCK(CONCAT(DATABASE(),':lamp-report-v18'),10)=1),1,0);
INSERT INTO lamp_v18_guard SELECT IF(((SELECT COUNT(*) FROM mdm_product WHERE product_code IN ('LAMP-HEAD','LAMP-ARM','LAMP-BASE-L100','LAMP-BASE-L200','LAMP-L100','LAMP-L200') AND deleted_flag=0 AND preparation_controlled=1)=6),1,0);
INSERT INTO lamp_v18_guard SELECT IF((NOT EXISTS(SELECT 1 FROM mdm_product_parameter x JOIN mdm_product p ON p.product_id=x.product_id WHERE p.product_code LIKE 'LAMP-%' AND x.deleted_flag=0 AND x.status<>'DRAFT')),1,0);
INSERT INTO lamp_v18_guard SELECT IF((NOT EXISTS(SELECT 1 FROM process_route WHERE route_code LIKE 'LAMP-%' AND deleted_flag=0 AND status NOT IN ('DRAFT','DISABLE'))),1,0);
INSERT INTO lamp_v18_guard SELECT IF((NOT EXISTS(SELECT 1 FROM qms_inspection_scheme WHERE scheme_code LIKE 'LAMP-%' AND deleted_flag=0 AND status NOT IN ('DRAFT','DISABLE'))),1,0);
INSERT INTO lamp_v18_guard SELECT IF((NOT EXISTS(SELECT 1 FROM qms_inspection_standard x JOIN mdm_product p ON p.product_id=x.product_id WHERE p.product_code LIKE 'LAMP-%' AND x.deleted_flag=0 AND x.confirmation_status<>'DRAFT')),1,0);
INSERT INTO lamp_v18_guard SELECT IF((NOT EXISTS(SELECT 1 FROM mfg_production_order x JOIN mdm_product p ON p.product_id=x.product_id WHERE p.product_code LIKE 'LAMP-%' AND x.deleted_flag=0)),1,0);
INSERT INTO lamp_v18_guard SELECT IF((NOT EXISTS(SELECT 1 FROM mfg_work_order x JOIN mdm_product p ON p.product_id=x.product_id WHERE p.product_code LIKE 'LAMP-%' AND x.deleted_flag=0)),1,0);
INSERT INTO lamp_v18_guard SELECT IF((NOT EXISTS(SELECT 1 FROM trace_product_lot x JOIN mdm_product p ON p.product_id=x.product_id WHERE p.product_code LIKE 'LAMP-%' AND x.deleted_flag=0)),1,0);
INSERT INTO lamp_v18_guard SELECT IF((NOT EXISTS(SELECT 1 FROM qms_inspection_order x JOIN qms_inspection_scheme s ON s.scheme_id=x.scheme_id WHERE s.scheme_code LIKE 'LAMP-%' AND x.deleted_flag=0)),1,0);
INSERT INTO lamp_v18_guard SELECT IF((NOT EXISTS(SELECT 1 FROM wms_inventory i JOIN mdm_material m ON m.material_id=i.material_id WHERE m.material_code LIKE 'LAMP-%' AND i.deleted_flag=0)),1,0);
