INSERT INTO qms_inspection_item(item_code,item_name,item_type,inspection_method,unit_id,remark,created_time) SELECT 'LAMP18-QI-APPEARANCE','结构外观与配套','PERFORMANCE','无缺件、破裂或松脱；配套与型号、BOM一致',NULL,'LAMP_REPORT_V18',NOW() WHERE NOT EXISTS(SELECT 1 FROM qms_inspection_item WHERE item_code='LAMP18-QI-APPEARANCE');
INSERT INTO qms_inspection_item(item_code,item_name,item_type,inspection_method,unit_id,remark,created_time) SELECT 'LAMP18-QI-INPUT-V','整灯输入电压','PERFORMANCE','11.4≤实测V≤12.6，极性正确，端点均包含',(SELECT unit_id FROM mdm_unit WHERE unit_code='LAMP-MEASURE-V' AND deleted_flag=0),'LAMP_REPORT_V18',NOW() WHERE NOT EXISTS(SELECT 1 FROM qms_inspection_item WHERE item_code='LAMP18-QI-INPUT-V');
INSERT INTO qms_inspection_item(item_code,item_name,item_type,inspection_method,unit_id,remark,created_time) SELECT 'LAMP18-QI-ADAPTER-A','适配器铭牌电流','PERFORMANCE','核对配套适配器铭牌DC12V/1A，不以负载实测电流代替铭牌额定值',(SELECT unit_id FROM mdm_unit WHERE unit_code='LAMP-MEASURE-A' AND deleted_flag=0),'LAMP_REPORT_V18',NOW() WHERE NOT EXISTS(SELECT 1 FROM qms_inspection_item WHERE item_code='LAMP18-QI-ADAPTER-A');
INSERT INTO qms_inspection_item(item_code,item_name,item_type,inspection_method,unit_id,remark,created_time) SELECT 'LAMP18-QI-MANUAL','手动三档与响应','PERFORMANCE','低/中/高控制设定30%/60%/100%，响应≤2s；不按照度百分比判定',NULL,'LAMP_REPORT_V18',NOW() WHERE NOT EXISTS(SELECT 1 FROM qms_inspection_item WHERE item_code='LAMP18-QI-MANUAL');
INSERT INTO qms_inspection_item(item_code,item_name,item_type,inspection_method,unit_id,remark,created_time) SELECT 'LAMP18-QI-AUTO','L200自动三档边界','PERFORMANCE','100/250/500lx为高/中/低；149/150/349/350lx为高/中/中/低；仅L200适用',NULL,'LAMP_REPORT_V18',NOW() WHERE NOT EXISTS(SELECT 1 FROM qms_inspection_item WHERE item_code='LAMP18-QI-AUTO');
INSERT INTO qms_inspection_item(item_code,item_name,item_type,inspection_method,unit_id,remark,created_time) SELECT 'LAMP18-QI-AGING','整灯连续老化','PERFORMANCE','高档连续≥60min、每架≤50台；无熄灭/闪烁/复位；中断本轮作废重计',(SELECT unit_id FROM mdm_unit WHERE unit_code='LAMP-MEASURE-MIN' AND deleted_flag=0),'LAMP_REPORT_V18',NOW() WHERE NOT EXISTS(SELECT 1 FROM qms_inspection_item WHERE item_code='LAMP18-QI-AGING');
