INSERT INTO lamp_v18_guard SELECT IF(((SELECT COUNT(*) FROM mdm_product_parameter WHERE product_id=(SELECT product_id FROM mdm_product WHERE product_code='LAMP-ARM' AND deleted_flag=0) AND parameter_code='POSITION_HOLD_SECONDS' AND deleted_flag=0 AND parameter_name<=>'定位保持时间' AND value_type<=>'INTEGER' AND parameter_value<=>'30' AND unit_label<=>'s' AND source_reference<=>'QST-LAMP-SPEC-01 V1.0；报告V1.8；项目设计输入，待实际验证' AND required_flag<=>'1')=1),1,0);
